describe('charts page', () => {
  describe('site charts gallery catalog', () => {
    it('lists every charts package family with a unique id; gives each family an import path, components and a non-empty contract; marks core fields required on cartesian and interaction families; keeps geo honest about offline schematic tiles in the sample note', () => {
      // lists every charts package family with a unique id
      {
        const ids = CHART_FAMILIES.map((f) => f.id);
        expect(ids).toEqual([
          'cartesian',
          'part-whole',
          'compact',
          'matrix',
          'flow',
          'geo',
          'interaction',
          'canvas',
        ]);
        expect(new Set(ids).size).toBe(ids.length);
      }
      for (const family of CHART_FAMILIES) {
        expect(family.importPath.startsWith('@texuli/charts/')).toBe(true);
        expect(family.components.length).toBeGreaterThan(0);
        expect(family.contract.length).toBeGreaterThan(0);
        expect(family.summary.length).toBeGreaterThan(10);
        expect(family.sampleNote.length).toBeGreaterThan(10);
        expect(familyPath(family.id)).toBe(`/charts-page/${family.id}/`);
        expect(familyById(family.id)).toEqual(family);
      }
      expect(requiredContractNames(familyById('cartesian')!)).toEqual(
        expect.arrayContaining(['title', 'description', 'series'])
      );
      expect(requiredContractNames(familyById('interaction')!)).toEqual(
        expect.arrayContaining(['series'])
      );
      expect(requiredContractNames(familyById('canvas')!)).toEqual(
        expect.arrayContaining(['series', 'renderer', 'title', 'description'])
      );
      // keeps geo honest about offline schematic tiles in the sample note
      {
        const geo = familyById('geo');
        expect(geo?.sampleNote.toLowerCase()).toMatch(/schematic|district|region/);
        expect(geo?.contract.some((c) => c.name === 'shape')).toBe(true);
      }
    });
  });
});

describe('color explorer', () => {
  describe('color explorer build', () => {
    it('builds themes with scales, roles, pairs and css vars; formats CSS, JSON and Tailwind exports', async () => {
      // builds themes with scales, roles, pairs and css vars
      {
        const themes = await buildColorExplorerThemes();
        expect(themes.length).toBeGreaterThan(10);
        const enterprise = themes.find((t) => t.id === 'enterprise-neutral');
        expect(enterprise).toBeDefined();
        expect(enterprise!.light.roles.length).toBeGreaterThan(20);
        expect(enterprise!.light.pairs.length).toBeGreaterThan(10);
        expect(Object.keys(enterprise!.light.scales.primary)).toContain('500');
        expect(enterprise!.light.cssVars['--tx-background']).toBeTruthy();
        expect(enterprise!.dark.cssVars['--tx-background']).toBeTruthy();
        expect(formatRatio_1(4.5)).toBe('4.50:1');
      }
      // formats CSS, JSON and Tailwind exports
      {
        const themes = await buildColorExplorerThemes();
        const theme = themes.find((t) => t.id === 'enterprise-neutral') ?? themes[0]!;
        const tw = explorerTailwindEntries();
        const css = cssVarsBlock(theme.id, 'light', theme.light.cssVars);
        expect(css).toContain(`[data-tx-theme='${theme.id}']`);
        expect(css).toContain('--tx-');
        const json = jsonTokenExport(theme, 'dark');
        const parsed = JSON.parse(json) as { mode: string; roles: Record<string, string> };
        expect(parsed.mode).toBe('dark');
        expect(parsed.roles.background).toBeTruthy();
        const map = tailwindMapExport(tw, theme.light.cssVars);
        expect(map).toContain('--color-');
        expect(buildExportText('css', theme, 'light', tw)).toContain('--tx-');
        expect(buildExportText('json', theme, 'light', tw)).toContain('"id"');
        expect(buildExportText('tailwind', theme, 'light', tw)).toContain('theme');
      }
    }, 240000);
  });
});

describe('component pages loader', () => {
  /**
   * Unit tests for the texuli.com component-pages generator loaders.
   */

  describe('site component pages loader', () => {
    it('loads a closed non-empty catalog sorted by id; resolves known display components with required sections; builds paths and a linear pager; groups pages without sharing mutable arrays; formats props and extracts keyboard rows from a11y prose', () => {
      // loads a closed non-empty catalog sorted by id
      {
        expect(COMPONENT_PAGES.length).toBeGreaterThan(20);
        const ids = COMPONENT_PAGES.map((p) => p.id);
        expect(ids).toEqual([...ids].sort((a, b) => a.localeCompare(b, 'en')));
        expect(new Set(ids).size).toBe(ids.length);
      }
      // resolves known display components with required sections
      {
        const badge = getComponentPage('badge');
        expect(badge).toBeDefined();
        expect(badge?.group).toBe('display');
        expect(badge?.label).toBeTruthy();
        expect(badge?.props.length).toBeGreaterThan(0);
        expect(badge?.useWhen.length).toBeGreaterThan(0);
        expect(badge?.dontUseWhen.length).toBeGreaterThan(0);
        expect(a11yLines(badge!.a11y).length).toBeGreaterThan(0);
      }
      // builds paths and a linear pager
      {
        expect(componentPagePath('badge')).toBe('/component-pages/badge/');
        const first = COMPONENT_PAGES[0]!;
        const second = COMPONENT_PAGES[1]!;
        const last = COMPONENT_PAGES[COMPONENT_PAGES.length - 1]!;
        expect(componentPager(first.id).prev).toBeUndefined();
        expect(componentPager(first.id).next?.id).toBe(second.id);
        expect(componentPager(last.id).next).toBeUndefined();
        expect(componentPager(last.id).prev?.id).toBe(
          COMPONENT_PAGES[COMPONENT_PAGES.length - 2]!.id
        );
      }
      // groups pages without sharing mutable arrays
      {
        const byGroup = componentPagesByGroup();
        expect(byGroup.size).toBeGreaterThanOrEqual(5);
        for (const group of ['content', 'display', 'forms', 'layouts', 'overlays']) {
          expect(byGroup.has(group), group).toBe(true);
          expect(byGroup.get(group)!.length).toBeGreaterThan(0);
        }
      }
      // formats props and extracts keyboard rows from a11y prose
      {
        expect(formatExampleProps({ variant: 'success' })).toContain('"variant"');
        const rows = keyboardRows('Press Enter or Escape to dismiss. Tab moves focus.');
        expect(rows.some((r) => /Enter/i.test(r.key))).toBe(true);
        const fallback = keyboardRows('Color is never the only cue.');
        expect(fallback).toHaveLength(1);
        expect(fallback[0]!.key).toBe('—');
      }
    });
  });
});

describe('evidence loaders', () => {
  describe('site evidence loaders', () => {
    it('maps components to size entries and budgets; resolves behavior scenarios and counts their checks; builds evidence cards for button and dialog', () => {
      // maps components to size entries and budgets
      {
        expect(sizeEntryForComponent('button', 'texuli')).toBe('texuli/button');
        expect(sizeEntryForComponent('dialog', '@texuli/primitives')).toBe(
          '@texuli/primitives/dialog'
        );
        expect(sizeEntryForComponent('select-trigger', 'texuli')).toBe('texuli/select-trigger');
        const budget = resolveGzipBudget('@texuli/primitives/dialog');
        expect(budget).toBeTypeOf('number');
        expect(budget!).toBeGreaterThan(1000);
        expect(formatBytes(11589)).toMatch(/KiB/);
      }
      resetBehaviorScenarioCache();
      expect(guessBehaviorScenario('dialog')).toBe('dialog');
      expect(guessBehaviorScenario('dropdown-menu-trigger')).toBe('dropdown-menu');
      expect(guessBehaviorScenario('layout-sidebar')).toBeUndefined();
      expect(hasBehaviorScenario('dialog')).toBe(true);
      expect(behaviorCheckCount('dialog')).toBeGreaterThan(0);
      expect(behaviorCheckCount('no-such-scenario')).toBe(0);
      // builds evidence cards for button and dialog
      {
        const button = evidenceForComponent('button', 'texuli');
        expect(button.id).toBe('button');
        expect(button.size.entry).toBe('texuli/button');
        expect(button.browsers.projects).toEqual(['chromium', 'webkit', 'mobile']);
        expect(button.axe.suites.length).toBeGreaterThan(0);
        expect(button.asOf).toMatch(/^\d{4}-\d{2}-\d{2}$/);

        const dialog = evidenceForComponent('dialog', '@texuli/primitives');
        expect(dialog.behavior.scenario).toBe('dialog');
        expect(dialog.behavior.status).toBe('checked');
        expect(dialog.behavior.checks).toBeGreaterThan(0);
        expect(button.behavior.status).toBe('n/a');
        expect(dialog.size.gzipMeasured).toBe(11589);
        expect(dialog.size.gzipBudget).toBeTypeOf('number');
      }
    });
  });
});

